                      ? "rgba(255,255,255,0.55)"
                      : "rgba(10,42,74,0.5)",
                  fontSize: scale(9.5),
                  fontFamily: fonts.medium,
                  marginTop: 1,
                }}
              >
                {mode === "dark"
                  ? "Brighter white = more foot traffic"
                  : "Brighter green = more foot traffic"}
              </Text>
            </View>
            <View
              style={[
                st.stepsPill,
                isActive
                  ? { backgroundColor: accent(0.14), borderColor: accent(0.4) }
                  : {
                      backgroundColor: "rgba(150,150,150,0.12)",
                      borderColor: "rgba(150,150,150,0.3)",
                    },
              ]}
            >
              <Ionicons
                name="footsteps"
                size={scale(13)}
                color={
                  isActive ? (mode === "dark" ? "#FFFFFF" : NAVY) : c.muted
                }
              />
              <Text
                style={[
                  st.stepsPillText,
                  { color: isActive ? c.text : c.muted },
                ]}
              >
                {isActive ? <CountUpText value={1248} style={st.stepsPillText} /> : "--"}
              </Text>
            </View>
          </View>

          <View
            style={[
              st.kineticRow,
              isActive
                ? { borderColor: accent(0.35), backgroundColor: accent(0.1) }
                : {
                    borderColor: "rgba(150,150,150,0.25)",
                    backgroundColor: "rgba(150,150,150,0.08)",
                  },
            ]}
          >
            <Ionicons
              name="footsteps"
              size={scale(14)}
              color={
                isActive ? (mode === "dark" ? "#FFFFFF" : "#B4771B") : c.muted
              }
            />
            <Text
              style={[
                st.kineticText,
                {
                  color:
                    mode === "dark"
                      ? "rgba(255,255,255,0.75)"
                      : "rgba(10,42,74,0.7)",
                },
              ]}
            >
              Footsteps converted today
            </Text>
            <Text
              style={{
                color: isActive
                  ? mode === "dark"
                    ? "#FFFFFF"
                    : "#4CA83E"
                  : c.muted,
                fontSize: scale(11),
                fontFamily: fonts.extrabold,
              }}
            >
              {isActive ? "+0.34 kWh" : "-- kWh"}
            </Text>
          </View>

          <TourSpot id="heatmap">
          <View
            style={[
              st.heatGrid,
              {
                backgroundColor: "#1D1A2A",
              },
            ]}
          >
            {Array.from({ length: HEAT_ROWS }, (_, r) => (
              <View key={r} style={st.heatRow}>
                {Array.from({ length: HEAT_COLS }, (_, col) => {
                  const i = r * HEAT_COLS + col;
                  const v = isActive ? heatTiles[i] : 0.05; // Drop value strictly to baseline if offline
                  const active = activeTile === i;
                  return (
                    <Pressable
                      key={col}
                      onPress={() => {
                        if (isActive) setActiveTile(active ? null : i);
                      }}
                      style={[
                        st.heatTile,
                        {
                          backgroundColor: heatColor(v, mode),
                          shadowColor: "#090B12",
                          shadowOpacity: isActive ? v * 0.9 : 0,
                          shadowRadius: scale(9),
                          borderWidth: 1,
                          borderColor: active && isActive ? "#FBA94C" : "rgba(255,255,255,0.22)",
                        },
                        active &&
                          isActive && [
                            st.heatTileActive,
                            {
                              borderColor:
                                "#FBA94C",
                            },
                          ],
                      ]}
                    >
                      <View
                        pointerEvents="none"
                        style={[
                          st.heatTileDepth,
                          { backgroundColor: v > 0.75 ? "#9A3412" : "#431407" },
                        ]}
                      />
                      <LinearGradient
                        pointerEvents="none"
                        colors={["rgba(255,255,255,0.28)", "rgba(255,255,255,0.04)", "rgba(0,0,0,0.28)"]}
                        locations={[0, 0.34, 1]}
                        style={StyleSheet.absoluteFill}
                      />
                      <View pointerEvents="none" style={st.heatTileHighlight} />
                      <View pointerEvents="none" style={st.heatTileDiagonal} />
                      <View pointerEvents="none" style={st.heatTileBevelTop} />
                      <View pointerEvents="none" style={st.heatTileBevelBottom} />
                      {active && isActive && (
                        <Ionicons
                          name="footsteps"
                          size={scale(11)}
                          color="#FFFFFF"
                        />
                      )}
                    </Pressable>
                  );
                })}
              </View>
            ))}
          </View>
          </TourSpot>

          <View
            style={{
              flexDirection: "row",
              alignItems: "center",
              justifyContent: "center",
              gap: scale(6),
              marginTop: scale(10),
            }}
          >
            <Text
              style={[
                st.legendText,
                {
                  color:
                    mode === "dark"
                      ? "rgba(255,255,255,0.5)"
                      : "rgba(10,42,74,0.5)",
                },
              ]}
            >
              Less
            </Text>
            <View
              style={{
                flexDirection: "row",
                gap: scale(3),
                opacity: isActive ? 1 : 0.4,
              }}
            >
              {[0.1, 0.35, 0.6, 0.82, 0.98].map((v, i) => (
                <View
                  key={i}
                  style={[
                    st.legendSwatch,
                    { backgroundColor: heatColor(v, mode) },
                  ]}
                />
              ))}
            </View>
            <Text
              style={[
                st.legendText,
                {
                  color:
                    mode === "dark"
                      ? "rgba(255,255,255,0.5)"
                      : "rgba(10,42,74,0.5)",
                },
              ]}
            >
              More
            </Text>
          </View>

          {activeTile !== null && isActive && (
            <Text
              style={[
                st.tileInfo,
                {
                  color:
                    mode === "dark"
                      ? "rgba(255,255,255,0.7)"
                      : "rgba(10,42,74,0.65)",
                },
              ]}
            >
              Tile #{activeTile + 1} ΓÇö {Math.round(heatTiles[activeTile] * 480)}{" "}
              crossings today
            </Text>
          )}
        </Card>
      </EnterView>

      <View style={{ height: scale(28) }} />
    </ScreenShell>
  );
}

