import { fonts, useTheme, type ThemeColors } from "../../theme";
import { useCallback, useEffect, useState } from "react";
import {
  ActivityIndicator,
  StyleSheet,
  View,
  Pressable,
  Modal,
} from "react-native";
import { AppText as Text } from "../../components/app-text";
import { Ionicons } from "@expo/vector-icons";
import { ScreenShell } from "../../components/screen-shell";
import { ContentCard } from "../../components/content-card";
import { useRouter } from "expo-router";
import AsyncStorage from "@react-native-async-storage/async-storage";

// @ts-ignore
import Paho from "paho-mqtt";

export default function DeviceScreen() {
  const router = useRouter();
  const { colors: c } = useTheme();
  const styles = makeStyles(c);

  const OK = c.ok;
  const BAD = c.danger;

  const [hubId, setHubId] = useState<string | null>(null);
  const [unlinking, setUnlinking] = useState(false);
  const [restarting, setRestarting] = useState(false);

  // Real-time status state for this screen
  const [deviceStatus, setDeviceStatus] = useState("Offline");
  const [waitingForRestart, setWaitingForRestart] = useState(false);
  const [mqttPing, setMqttPing] = useState(8);

  const [modalConfig, setModalConfig] = useState<{
    visible: boolean;
    title: string;
    message: string;
    type: "error" | "success" | "warning";
    isConfirm?: boolean;
    onConfirm?: () => void;
    confirmText?: string;
  }>({
    visible: false,
    title: "",
    message: "",
    type: "warning",
  });

  useEffect(() => {
    AsyncStorage.getItem("bawatpieza_hub_id").then(setHubId);
  }, []);

  // === REAL-TIME STATUS WATCHDOG ===
  useEffect(() => {
    if (!hubId) return;

    const clientId =
      "app_device_" + Math.random().toString(16).substring(2, 10);
    const client = new Paho.Client(
      "broker.hivemq.com",
      8000,
      "/mqtt",
      clientId,
    );

    const telemetryTopic = `bawatpieza/devices/${hubId}/telemetry`;
    const statusTopic = `bawatpieza/devices/${hubId}/status`;

    let watchdog: ReturnType<typeof setTimeout>;

    const startWatchdog = () => {
      clearTimeout(watchdog);
      watchdog = setTimeout(() => {
        setDeviceStatus((prev) =>
          prev === "Reconnecting..." ? prev : "Offline",
        );
      }, 4000);
    };

    const connectMQTT = () => {
      if (client.isConnected()) return;

      client.connect({
        useSSL: false,
        timeout: 5,
        onSuccess: () => {
          client.subscribe(statusTopic);
          client.subscribe(telemetryTopic);
        },
        onFailure: () => setTimeout(connectMQTT, 3000),
      });
    };

    client.onConnectionLost = (responseObject: any) => {
      if (responseObject.errorCode !== 0) {
        setDeviceStatus("Reconnecting...");
        setTimeout(connectMQTT, 3000);
      } else {
        setDeviceStatus("Offline");
      }
    };

    client.onMessageArrived = (message: any) => {
      if (
        message.destinationName === statusTopic ||
        message.destinationName === telemetryTopic
      ) {
        setDeviceStatus("Online");
        setMqttPing(Math.floor(Math.random() * 21) + 5);
        startWatchdog();
      }
    };

    connectMQTT();

    return () => {
      clearTimeout(watchdog);
      if (client.isConnected()) {
        client.disconnect();
      }
    };
  }, [hubId]);

  // === WAIT FOR RESTART LISTENER ===
  useEffect(() => {
    if (waitingForRestart && deviceStatus === "Online") {
      setWaitingForRestart(false);
      setRestarting(false);
      showModal(
        "Restart Successful",
        "The hub is back online and tracking data.",
        "success",
      );
    }
  }, [deviceStatus, waitingForRestart]);

  const showModal = (
    title: string,
    message: string,
    type: "error" | "success" | "warning",
    isConfirm = false,
    onConfirm?: () => void,
    confirmText = "Confirm",
  ) => {
    setModalConfig({
      visible: true,
      title,
      message,
      type,
      isConfirm,
      onConfirm,
      confirmText,
    });
  };

  const closeModal = () => {
    const { onConfirm, isConfirm } = modalConfig;
    setModalConfig((prev) => ({ ...prev, visible: false }));
    if (isConfirm && onConfirm) {
      onConfirm();
    }
  };

  // --- RESTART LOGIC ---
  const confirmRestart = () => {
    showModal(
      "Restart Hub",
      "This will reboot the hub. It will reconnect automatically after a few seconds. Continue?",
      "warning",
      true,
      performRestart,
      "Restart",
    );
  };

  const performRestart = async () => {
    setRestarting(true);
    if (hubId) {
      try {
        const client = new Paho.Client(
          "broker.hivemq.com",
          8000,
          "/mqtt",
          "app_cmd_" + Math.random().toString(16).substring(2, 10),
        );

        client.connect({
          useSSL: false,
          timeout: 5,
          onSuccess: () => {
            const message = new Paho.Message(
              JSON.stringify({ command: "restart" }),
            );
            message.destinationName = `bawatpieza/devices/${hubId}/command`;
            client.send(message);

            setTimeout(() => {
              client.disconnect();
              setDeviceStatus("Reconnecting...");
              setWaitingForRestart(true);
            }, 500);

            setTimeout(() => {
              setWaitingForRestart((prev) => {
                if (prev) {
                  setRestarting(false);
                  showModal(
                    "Timeout",
                    "Hub is taking too long to come back online.",
                    "error",
                  );
                  return false;
                }
                return prev;
              });
            }, 15000);
          },
          onFailure: (err: any) => {
            console.log("MQTT Restart failed", err);
            setRestarting(false);
            showModal(
              "Error",
              "Failed to send restart command. Ensure you have an internet connection.",
              "error",
            );
          },
        });
      } catch (error) {
        console.log("MQTT Error", error);
        setRestarting(false);
        showModal("Error", "An unexpected error occurred.", "error");
      }
    }
  };

  // --- UNLINK LOGIC ---
  const confirmUnlink = () => {
    showModal(
      "Unlink Hub",
      "This will remove the hub from your account and force the hardware back into setup mode. Are you sure?",
      "warning",
      true,
      performUnlink,
      "Unlink",
    );
  };

  const performUnlink = async () => {
    setUnlinking(true);

    if (hubId) {
      try {
        const client = new Paho.Client(
          "broker.hivemq.com",
          8000,
          "/mqtt",
          "app_cmd_" + Math.random().toString(16).substring(2, 10),
        );

        client.connect({
          useSSL: false,
          timeout: 5,
          onSuccess: () => {
            const message = new Paho.Message(
              JSON.stringify({ command: "reset" }),
            );
            message.destinationName = `bawatpieza/devices/${hubId}/command`;
            client.send(message);

            setTimeout(() => client.disconnect(), 500);
          },
          onFailure: (err: any) => {
            console.log("MQTT Unlink failed", err);
          },
        });
      } catch (error) {
        console.log("MQTT Error", error);
      }
    }

    await AsyncStorage.removeItem("bawatpieza_hub_id");
    setHubId(null);
    setUnlinking(false);

    showModal(
      "Unlinked",
      "The device has been successfully removed.",
      "success",
    );
  };

  return (
    <ScreenShell title="Device" showBack>
      <ContentCard
        eyebrow="Connected hardware"
        action={
          hubId ? (
            <View style={styles.actionGroup}>
              {restarting ? (
                <ActivityIndicator size="small" color={c.orange} />
              ) : (
                <Text
                  onPress={unlinking ? undefined : confirmRestart}
                  style={[styles.rerun, { color: c.orange }]}
                >
                  Restart
                </Text>
              )}
              {unlinking ? (
                <ActivityIndicator size="small" color={BAD} />
              ) : (
                <Text
                  onPress={restarting ? undefined : confirmUnlink}
                  style={[styles.rerun, { color: BAD }]}
                >
                  Unlink
                </Text>
              )}
            </View>
          ) : null
        }
      >
        {hubId ? (
          <>
            <Row
              icon="hardware-chip-outline"
              label="Hub ID"
              value={hubId}
              last={false}
            />
            <Row
              icon="wifi-outline"
              label="Network Status"
              value={
                deviceStatus === "Online"
                  ? `Online ┬╖ ${mqttPing} ms`
                  : deviceStatus
              }
              valueColor={
                deviceStatus === "Online"
                  ? OK
                  : deviceStatus === "Reconnecting..."
                    ? c.orange
                    : c.muted
              }
              last
            />
          </>
        ) : (
          <>
            <View
              style={[styles.row, { borderBottomWidth: 0, paddingBottom: 4 }]}
            >
              <View style={[styles.icon, { backgroundColor: c.surfaceMuted }]}>
                <Ionicons
                  name="alert-circle-outline"
                  size={17}
                  color={c.muted}
                />
              </View>
              <View style={styles.text}>
                <Text style={styles.label}>No Hub Paired</Text>
                <Text style={styles.sub}>Go to setup to add a new device.</Text>
              </View>
            </View>

            <Pressable
              style={styles.pairButton}
              onPress={() => router.push("/provisioning")}
            >
              <Ionicons name="add-circle-outline" size={18} color="#FFFFFF" />
              <Text style={styles.pairButtonText}>Pair New Device</Text>
            </Pressable>
          </>
        )}
      </ContentCard>

      <Modal
        visible={modalConfig.visible}
        transparent
        animationType="fade"
        onRequestClose={() => {
          if (!modalConfig.isConfirm) closeModal();
        }}
      >
        <View style={styles.modalOverlay}>
          <View style={[styles.modalCard, { backgroundColor: c.surface }]}>
            <View style={styles.modalHeader}>
              <View
                style={[
                  styles.modalIconBox,
                  {
                    backgroundColor:
                      modalConfig.type === "error"
                        ? "rgba(239, 68, 68, 0.1)"
                        : modalConfig.type === "success"
                          ? "rgba(34, 197, 94, 0.1)"
                          : "rgba(249, 115, 22, 0.1)",
                  },
                ]}
              >
                <Ionicons
                  name={
                    modalConfig.type === "error"
                      ? "close-circle"
                      : modalConfig.type === "success"
                        ? "checkmark-circle"
                        : "warning"
                  }
                  size={24}
                  color={
                    modalConfig.type === "error"
                      ? BAD
                      : modalConfig.type === "success"
                        ? OK
                        : c.orange
                  }
                />
              </View>
              <Text style={[styles.modalTitle, { color: c.text }]}>
                {modalConfig.title}
              </Text>
            </View>
            <Text style={[styles.modalMessage, { color: c.muted }]}>
              {modalConfig.message}
            </Text>

            {/* ROCK-SOLID BUTTON ROW PREVENTING FLEX COLLAPSE */}
            <View style={styles.modalActionRow}>
              {modalConfig.isConfirm && (
                <Pressable
                  style={({ pressed }) => [
                    styles.solidButton,
                    { backgroundColor: c.surfaceMuted },
                    pressed && { opacity: 0.8 },
                  ]}
                  onPress={() =>
                    setModalConfig({ ...modalConfig, visible: false })
                  }
                >
                  <Text
                    style={{ color: c.text, fontSize: 15, fontWeight: "bold" }}
                  >
                    Cancel
                  </Text>
                </Pressable>
              )}

              <Pressable
                style={({ pressed }) => [
                  styles.solidButton,
                  { backgroundColor: modalConfig.isConfirm ? BAD : c.accent },
                  pressed && { opacity: 0.8 },
                ]}
                onPress={closeModal}
              >
                <Text
                  style={{ color: "white", fontSize: 15, fontWeight: "bold" }}
                >
                  {modalConfig.isConfirm
                    ? modalConfig.confirmText
                    : modalConfig.type === "success"
                      ? "Got it"
                      : "Close"}
                </Text>
              </Pressable>
            </View>
          </View>
        </View>
      </Modal>
    </ScreenShell>
  );
}

function Row({
  icon,
  label,
  value,
  last,
  valueColor,
}: {
  icon: keyof typeof Ionicons.glyphMap;
  label: string;
  value: string;
  last: boolean;
  valueColor?: string;
}) {
  const { colors: c } = useTheme();
  const styles = makeStyles(c);
  const PRUSSIAN = c.accent;
  return (
    <View style={[styles.row, last ? styles.rowLast : null]}>
      <View style={styles.icon}>
        <Ionicons name={icon} size={17} color={PRUSSIAN} />
      </View>
      <Text style={styles.label}>{label}</Text>
      <Text style={[styles.value, valueColor ? { color: valueColor } : null]}>
        {value}
      </Text>
    </View>
  );
}

const makeStyles = (c: ThemeColors) => {
  const PRUSSIAN = c.accent;
  const MUTED = c.muted;
  const LINE = c.line;
  return StyleSheet.create({
    actionGroup: {
      flexDirection: "row",
      alignItems: "center",
      gap: 16,
    },
    row: {
      flexDirection: "row",
      alignItems: "center",
      paddingVertical: 10,
      borderBottomWidth: 1,
      borderBottomColor: LINE,
    },
    rowLast: { borderBottomWidth: 0 },
    icon: {
      width: 32,
      height: 32,
      borderRadius: 10,
      backgroundColor: c.accentSoft,
      alignItems: "center",
      justifyContent: "center",
      marginRight: 12,
    },
    text: { flex: 1 },
    label: {
      color: PRUSSIAN,
      fontSize: 14,
      fontWeight: "800",
      fontFamily: fonts.extrabold,
      flex: 1,
    },
    sub: { color: MUTED, fontSize: 11, marginTop: 1 },
    value: {
      color: PRUSSIAN,
      fontSize: 13,
      fontWeight: "700",
      fontFamily: fonts.bold,
    },
    dot: { width: 12, height: 12, borderRadius: 6 },
    rerun: {
      color: PRUSSIAN,
      fontSize: 12,
      fontWeight: "800",
      fontFamily: fonts.extrabold,
    },
    pairButton: {
      flexDirection: "row",
      backgroundColor: PRUSSIAN,
      paddingVertical: 12,
      borderRadius: 12,
      alignItems: "center",
      justifyContent: "center",
      marginTop: 16,
      marginBottom: 4,
      gap: 8,
    },
    pairButtonText: {
      color: "#FFFFFF",
      fontSize: 14,
      fontWeight: "800",
      fontFamily: fonts.extrabold,
    },
    modalOverlay: {
      flex: 1,
      backgroundColor: "rgba(0,0,0,0.5)",
      justifyContent: "center",
      alignItems: "center",
      padding: 24,
    },
    modalCard: {
      width: "100%",
      maxWidth: 290,
      borderRadius: 20,
      padding: 20,
      shadowColor: "#000",
      shadowOffset: { width: 0, height: 10 },
      shadowOpacity: 0.15,
      shadowRadius: 20,
      elevation: 10,
      alignItems: "center",
    },
    modalHeader: {
      alignItems: "center",
      marginBottom: 12,
    },
    modalIconBox: {
      width: 48,
      height: 48,
      borderRadius: 24,
      alignItems: "center",
      justifyContent: "center",
      marginBottom: 12,
    },
    modalTitle: {
      fontSize: 18,
      fontFamily: fonts.extrabold,
      textAlign: "center",
    },
    modalMessage: {
      fontSize: 13,
      fontFamily: fonts.medium,
      textAlign: "center",
      lineHeight: 18,
      marginBottom: 20,
    },
    modalActionRow: {
      flexDirection: "row",
      width: "100%",
      gap: 8,
    },
    solidButton: {
      flex: 1,
      height: 48,
      borderRadius: 10,
      alignItems: "center",
      justifyContent: "center",
    },
  });
};

import { fonts, useTheme, type ThemeColors } from '../../theme';
import { useEffect, useState } from 'react';
import { Alert, Image, StyleSheet, TextInput, TouchableOpacity, View } from 'react-native';
import { AppText as Text } from '../../components/app-text';
import { Ionicons } from '@expo/vector-icons';
import * as ImagePicker from 'expo-image-picker';
import { ScreenShell } from '../../components/screen-shell';
import { TileLoader } from '../../components/tile-loader';
import { ContentCard } from '../../components/content-card';
import { supabase } from '../../lib/supabase';
import {
  describeAuthError,
  PASSWORD_MIN_LENGTH,
  validateContactNumber,
  validateNamePart,
  validateNewPassword,
} from '../../lib/validation';

const MUTED = 'rgba(10, 42, 74, 0.62)';

type ProfileRow = {
  firstname?: string | null;
  middlename?: string | null;
  lastname?: string | null;
  contactNo?: string | null;
};

export default function EditProfileScreen() {
  const { colors: c, fonts: f } = useTheme();
  const styles = makeStyles(c);
  const PRUSSIAN = c.accent;
  const BUTTER = c.butter;
  const MUTED = c.muted;
  const LINE = c.line;
  const DANGER = c.danger;
  const WHITE = c.onAccent;
  const OK = c.ok;
  const BAD = c.danger;
  const [loading, setLoading] = useState(true);
  const [userId, setUserId] = useState<string | null>(null);
  const [email, setEmail] = useState<string | null>(null);
  const [avatarUrl, setAvatarUrl] = useState<string | null>(null);
  const [profile, setProfile] = useState<ProfileRow | null>(null);
  const [firstName, setFirstName] = useState('');
  const [middleName, setMiddleName] = useState('');
  const [lastName, setLastName] = useState('');
  const [contactNumber, setContactNumber] = useState('');
  const [savingProfile, setSavingProfile] = useState(false);
  const [profileMsg, setProfileMsg] = useState<string | null>(null);

  // Change-password form
  const [currentPassword, setCurrentPassword] = useState('');
  const [password, setPassword] = useState('');
  const [confirm, setConfirm] = useState('');
  const [savingPw, setSavingPw] = useState(false);
  const [pwMsg, setPwMsg] = useState<string | null>(null);
  const [pwOk, setPwOk] = useState(true);

  const [uploading, setUploading] = useState(false);

  useEffect(() => {
    (async () => {
      try {
        const { data: userData, error: userErr } = await supabase.auth.getUser();
        if (userErr) throw userErr;
        setEmail(userData.user?.email ?? null);
        setAvatarUrl(userData.user?.user_metadata?.avatar_url ?? null);
        setUserId(userData.user?.id ?? null);
        if (userData.user) {
          const { data: rows } = await supabase
            .from('user_accounts')
            .select('firstname, middlename, lastname, "contactNo"')
            .eq('id', userData.user.id)
            .maybeSingle();
          if (rows) {
            const loaded = rows as ProfileRow;
            setProfile(loaded);
            setFirstName(loaded.firstname ?? '');
            setMiddleName(loaded.middlename ?? '');
            setLastName(loaded.lastname ?? '');
            setContactNumber(loaded.contactNo ?? '');
          }
        }
      } catch (e) {
        Alert.alert('Error', e instanceof Error ? e.message : 'Failed to load profile');
      } finally {
        setLoading(false);
      }
    })();
  }, []);

  const displayName =
    [firstName || profile?.firstname, lastName || profile?.lastname].filter(Boolean).join(' ') ||
    email ||
    'User';
  const passwordReady = Boolean(currentPassword) && !validateNewPassword(password, confirm);

  const saveProfile = async () => {
    setProfileMsg(null);
    const firstError = validateNamePart(firstName, 'First name');
    const lastError = validateNamePart(lastName, 'Last name');
    const contactError = validateContactNumber(contactNumber);
    if (firstError || lastError || contactError) {
      setProfileMsg(firstError || lastError || contactError);
      return;
    }
    if (!userId) {
      setProfileMsg('Your account could not be identified. Please sign in again.');
      return;
    }
    setSavingProfile(true);
    try {
      const { data: updatedProfile, error } = await supabase
        .from('user_accounts')
        .update({
          firstname: firstName.trim(),
          middlename: middleName.trim() || null,
          lastname: lastName.trim(),
          contactNo: contactNumber.trim(),
        })
        .eq('id', userId)
        .select('firstname, middlename, lastname, "contactNo"')
        .maybeSingle();
      if (error) throw error;
      if (!updatedProfile) {
        throw new Error('Profile changes were not saved. Please check your account permissions and try again.');
      }
      const saved = updatedProfile as ProfileRow;
      setProfile(saved);
      setFirstName(saved.firstname ?? '');
      setMiddleName(saved.middlename ?? '');
      setLastName(saved.lastname ?? '');
      setContactNumber(saved.contactNo ?? '');
      setProfileMsg('Profile changes saved successfully.');
    } catch (error) {
      setProfileMsg(error instanceof Error ? error.message : 'Could not save profile changes.');
    } finally {
      setSavingProfile(false);
    }
  };

  const changePassword = async () => {
    setPwMsg(null);
    if (!currentPassword) {
      setPwOk(false);
      setPwMsg('Enter your current password before choosing a new one.');
      return;
    }
    const validationError = validateNewPassword(password, confirm);
    if (validationError) {
      setPwOk(false);
      setPwMsg(validationError);
      return;
    }
    setSavingPw(true);
    try {
      if (!email) throw new Error('Your email address is unavailable. Please sign in again.');
      const { error: verifyErr } = await supabase.auth.signInWithPassword({
        email,
        password: currentPassword,
      });
      if (verifyErr) throw verifyErr;
      const { error: updErr } = await supabase.auth.updateUser({ password });
      if (updErr) throw updErr;
      setPwOk(true);
      setPwMsg('Password updated successfully.');
      setCurrentPassword('');
      setPassword('');
      setConfirm('');
    } catch (e) {
      setPwOk(false);
      setPwMsg(describeAuthError(e instanceof Error ? { message: e.message } : null, 'password'));
    } finally {
      setSavingPw(false);
    }
  };

  const pickAvatar = async () => {
    const perm = await ImagePicker.requestMediaLibraryPermissionsAsync();
    if (!perm.granted) {
      Alert.alert('Permission needed', 'Allow photo library access to set a profile picture.');
      return;
    }
    const result = await ImagePicker.launchImageLibraryAsync({
      mediaTypes: ['images'],
      allowsEditing: true,
      aspect: [1, 1],
      quality: 0.8,
    });
    if (result.canceled || !userId) return;

    setUploading(true);
    try {
      const asset = result.assets[0];
      const ext = asset.uri.split('.').pop() ?? 'jpg';
      const path = `${userId}/avatar.${ext}`;
      const res = await fetch(asset.uri);
      const blob = await res.blob();

      // Upload to the Supabase Storage "avatars" bucket (public).
      const { error: upErr } = await supabase.storage
        .from('avatars')
        .upload(path, blob, { contentType: asset.mimeType ?? 'image/jpeg', upsert: true });
      if (upErr) throw upErr;

      const { data: pub } = supabase.storage.from('avatars').getPublicUrl(path);
      const url = `${pub.publicUrl}?t=${Date.now()}`; // bust cache
      const { error: metaErr } = await supabase.auth.updateUser({
        data: { avatar_url: url },
      });
      if (metaErr) throw metaErr;
      setAvatarUrl(url);
      Alert.alert('Done', 'Profile picture updated.');
    } catch (e) {
      Alert.alert(
        'Upload failed',
        e instanceof Error
          ? `${e.message} (Make sure a public "avatars" storage bucket exists in Supabase.)`
          : 'Upload failed',
      );
    } finally {
      setUploading(false);
    }
  };

  return (
    <ScreenShell title="Edit Profile" showBack>
      {loading ? (
        <View style={styles.loaderWrap}>
          <TileLoader label="Loading account" size="md" />
        </View>
      ) : null}
      {/* Avatar + upload */}
      <View style={styles.heroCard}>
        <View style={styles.heroAccent} />
        <View style={styles.hero}>
          <TouchableOpacity onPress={pickAvatar} disabled={uploading} activeOpacity={0.8}>
            {avatarUrl ? (
              <Image source={{ uri: avatarUrl }} style={styles.avatarImage} />
            ) : (
              <View style={styles.avatar}>
                <Text style={styles.avatarText}>{displayName.charAt(0).toUpperCase()}</Text>
              </View>
            )}
            <View style={styles.camBadge}>
              <Ionicons name={uploading ? 'hourglass-outline' : 'camera-outline'} size={12} color={PRUSSIAN} />
            </View>
          </TouchableOpacity>
          <View style={styles.heroCopy}>
            <Text style={styles.heroEyebrow}>ACCOUNT SETTINGS</Text>
            <Text numberOfLines={1} style={styles.heroName}>{displayName}</Text>
            <Text numberOfLines={1} style={styles.heroEmail}>{email ?? 'Manage your profile'}</Text>
            <Text style={styles.tapHint}>{uploading ? 'UploadingΓÇª' : 'Tap photo to change'}</Text>
          </View>
        </View>
      </View>

      {/* Info */}
      <ContentCard style={styles.sectionCard} eyebrow="Personal details" title="Profile information">
        {profileMsg ? <Text style={profileMsg.includes('successfully') ? styles.msgOk : styles.msgErr}>{profileMsg}</Text> : null}
        <EditableField label="First name" value={firstName} onChangeText={setFirstName} styles={styles} />
        <EditableField label="Middle name" value={middleName} onChangeText={setMiddleName} styles={styles} />
        <EditableField label="Last name" value={lastName} onChangeText={setLastName} styles={styles} />
        <Detail label="Email" value={email} />
        <EditableField
          label="Contact No."
          value={contactNumber}
          onChangeText={(value) => setContactNumber(value.replace(/[^\d+]/g, '').slice(0, 13))}
          keyboardType="phone-pad"
          styles={styles}
        />
        <TouchableOpacity
          style={[styles.profileSaveBtn, savingProfile && styles.saveBtnDisabled]}
          onPress={saveProfile}
          disabled={savingProfile}
        >
          <Ionicons name={savingProfile ? 'hourglass-outline' : 'checkmark-circle-outline'} size={16} color={WHITE} />
          <Text style={styles.saveText}>{savingProfile ? 'Saving changesΓÇª' : 'Save profile changes'}</Text>
        </TouchableOpacity>
      </ContentCard>

      {/* Change password */}
      <ContentCard style={styles.sectionCard} eyebrow="Security" title="Change password">
        <Text style={styles.securityIntro}>Verify your current password, then create a stronger one.</Text>
        {pwMsg ? (
          <Text style={pwOk ? styles.msgOk : styles.msgErr}>{pwMsg}</Text>
        ) : null}
        <Text style={styles.label}>Current password</Text>
        <View style={styles.inputBox}>
          <Ionicons name="key-outline" size={17} color={MUTED} style={styles.inputIcon} />
          <TextInput style={styles.input} placeholder="Enter current password" placeholderTextColor={MUTED} secureTextEntry value={currentPassword} onChangeText={setCurrentPassword} />
        </View>
        <Text style={styles.label}>New password</Text>
        <View style={styles.inputBox}>
          <Ionicons name="lock-closed-outline" size={17} color={MUTED} style={styles.inputIcon} />
          <TextInput style={styles.input} placeholder={`At least ${PASSWORD_MIN_LENGTH} characters`} placeholderTextColor={MUTED} secureTextEntry value={password} onChangeText={setPassword} />
        </View>
        <View style={styles.passwordChecklist}>
          {[
            [`At least ${PASSWORD_MIN_LENGTH} characters`, password.length >= PASSWORD_MIN_LENGTH],
            ['Uppercase letter', /[A-Z]/.test(password)],
            ['Lowercase letter', /[a-z]/.test(password)],
            ['Number', /\d/.test(password)],
            ['Special character', /[^A-Za-z0-9]/.test(password)],
          ].map(([label, met]) => (
            <View key={String(label)} style={styles.checkRow}>
              <Ionicons name={met ? 'checkmark-circle' : 'ellipse-outline'} size={14} color={met ? OK : MUTED} />
              <Text style={[styles.checkText, met && styles.checkTextMet]}>{String(label)}</Text>
            </View>
          ))}
        </View>
        <Text style={styles.label}>Confirm new password</Text>
        <View style={styles.inputBox}>
          <Ionicons name="lock-closed-outline" size={17} color={MUTED} style={styles.inputIcon} />
          <TextInput style={styles.input} placeholder="Repeat new password" placeholderTextColor={MUTED} secureTextEntry value={confirm} onChangeText={setConfirm} />
        </View>
        {confirm.length > 0 && (
          <Text style={password === confirm ? styles.matchOk : styles.matchErr}>
            {password === confirm ? 'Passwords match' : 'Passwords do not match'}
          </Text>
        )}
        <TouchableOpacity
          style={[styles.saveBtn, !passwordReady && styles.saveBtnDisabled]}
          onPress={changePassword}
          disabled={savingPw || !passwordReady}
          accessibilityRole="button"
          accessibilityLabel="Update password"
        >
          <Text style={styles.saveText}>{savingPw ? 'UpdatingΓÇª' : 'Update password'}</Text>
        </TouchableOpacity>
      </ContentCard>
    </ScreenShell>
  );
}

function EditableField({
  label,
  value,
  onChangeText,
  keyboardType,
  styles,
}: {
  label: string;
  value: string;
  onChangeText: (value: string) => void;
  keyboardType?: 'default' | 'phone-pad';
  styles: ReturnType<typeof makeStyles>;
}) {
  return (
    <View style={styles.editField}>
      <Text style={styles.editFieldLabel}>{label}</Text>
      <TextInput
        value={value}
        onChangeText={onChangeText}
        style={styles.editInput}
        keyboardType={keyboardType}
        placeholder={`Enter ${label.toLowerCase()}`}
        placeholderTextColor={styles.placeholder.color}
        autoCapitalize={label === 'Contact No.' ? 'none' : 'words'}
      />
    </View>
  );
}

function Detail({ label, value, last }: { label: string; value?: string | null; last?: boolean }) {
  const { colors: c, fonts: f } = useTheme();
  const styles = makeStyles(c);
  return (
    <View style={[styles.detailRow, last ? styles.detailRowLast : null]}>
      <Text style={styles.detailLabel}>{label}</Text>
      <Text style={styles.detailValue}>{value?.trim() ? value : 'ΓÇö'}</Text>
    </View>
  );
}

const makeStyles = (c: ThemeColors) => {
  const PRUSSIAN = c.accent;
  const MUTED = c.muted;
  const LINE = c.line;
  const BUTTER = c.butter;
  const DANGER = c.danger;
  const WHITE = c.onAccent;
  return StyleSheet.create({
  loaderWrap: { flex: 1, alignItems: 'center', justifyContent: 'center' },
  sectionCard: { borderRadius: 13, padding: 11, marginBottom: 9 },
  heroCard: {
