    backgroundColor: c.surfaceMuted,
  },
  inputIcon: { marginRight: 6 },
  input: { flex: 1, fontSize: 12, color: PRUSSIAN },
  passwordChecklist: {
    backgroundColor: c.surfaceMuted,
    borderRadius: 8,
    paddingHorizontal: 8,
    paddingVertical: 6,
    marginTop: -4,
