  saveBtn: { backgroundColor: PRUSSIAN, borderRadius: 9, paddingVertical: 9, alignItems: 'center' },
  saveBtnDisabled: { opacity: 0.45 },
  saveText: { color: WHITE, fontSize: 11, fontWeight: '800', fontFamily: fonts.extrabold },
  detailRow: {
    flexDirection: 'row',
