import { useCallback, useEffect, useMemo, useState } from 'react';
import { ActivityIndicator, Pressable, StyleSheet, View } from 'react-native';
import AsyncStorage from '@react-native-async-storage/async-storage';
import { AppText as Text } from '../../components/app-text';
import { Ionicons } from '@expo/vector-icons';
import { ScreenShell } from '../../components/screen-shell';
import { TileLoader } from '../../components/tile-loader';
import { ContentCard } from '../../components/content-card';
import { useAuth } from '../../hooks/use-auth';
import { supabase } from '../../lib/supabase';
import { apiFetch } from '../../lib/api';
import { describeApiFailure } from '../../lib/network';
import { fonts, useTheme, type ThemeColors } from '../../theme';

/**
 * Notifications page ΓÇö the full in-app feed behind the bell.
 *
 * Data comes from `GET /notifications` (newest first, with an `unread`
 * count). Invite rows (`type === 'share_invite'`, `reference_id` = the
 * `share_invites` id) carry inline Accept / Decline buttons that hit
 * `POST /accounts/invites/:id/accept|decline` ΓÇö the same handshake the
 * Shared Users screen uses.
 *
 * Where the invited-user notification lives: `POST /accounts/invite`
 * (backend `routes/accounts.ts`) inserts a `notifications` row addressed to
 * the INVITEE with `type='share_invite'` + `reference_id=<invite id>`. The
 * inviter instead gets `share_accepted` / `share_declined` once the invitee
 * responds. So the person who was invited is the one who sees the
 * `share_invite` row ΓÇö here and in the bell dropdown.
 */
type Tone = 'danger' | 'warning' | 'notice' | 'success';

type Item = {
  id: string;
  kind: string;
  title: string;
  detail: string;
  time: string;
  tone: Tone;
  icon: keyof typeof Ionicons.glyphMap;
  refId: string | null;
  read: boolean;
};

type ApiNotification = {
  id: string;
  type: string;
  title: string;
  body: string | null;
  reference_id: string | null;
  read_at: string | null;
  created_at: string;
};

type NotificationCache = {
  notifications: ApiNotification[];
  unread: number;
  cachedAt: string;
};

const NOTIFICATION_CACHE_PREFIX = 'bawatpieza:notifications:';

function mapNotifications(notifications: ApiNotification[]): Item[] {
  return notifications.map((n) => {
    const mapped = toneForType(n.type);
    return {
      id: n.id, kind: n.type, title: n.title, detail: n.body ?? '',
      time: timeAgo(n.created_at), tone: mapped.tone, icon: mapped.icon,
      refId: n.reference_id, read: n.read_at !== null,
    };
  });
}

function toneForType(type: string): { icon: keyof typeof Ionicons.glyphMap; tone: Tone } {
  switch (type) {
    case 'share_invite':
      return { icon: 'person-add-outline', tone: 'notice' };
    case 'share_accepted':
      return { icon: 'people-outline', tone: 'success' };
    case 'share_declined':
      return { icon: 'close-circle-outline', tone: 'warning' };
    default:
      return { icon: 'notifications-outline', tone: 'notice' };
  }
}

function timeAgo(iso: string): string {
  const then = new Date(iso).getTime();
  if (Number.isNaN(then)) return '';
  const s = Math.max(0, Math.floor((Date.now() - then) / 1000));
  if (s < 60) return 'Just now';
  const m = Math.floor(s / 60);
  if (m < 60) return `${m} min ago`;
  const h = Math.floor(m / 60);
  if (h < 24) return `${h} hr ago`;
  const d = Math.floor(h / 24);
  if (d === 1) return 'Yesterday';
  return `${d} days ago`;
}

const PALETTE: Record<Tone, { background: string; icon: string }> = {
  danger: { background: '#FCE4E4', icon: '#D14343' },
  warning: { background: '#FCEDE4', icon: '#F06421' },
  notice: { background: '#FFF3DE', icon: '#F5A313' },
  success: { background: '#E5F5E5', icon: '#16A34A' },
};

export default function NotificationsScreen() {
  const { colors: c } = useTheme();
  const styles = makeStyles(c);

  const { session } = useAuth();

  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [items, setItems] = useState<Item[]>([]);
  const [unread, setUnread] = useState(0);
  const [respondingId, setRespondingId] = useState<string | null>(null);
  const [markingRead, setMarkingRead] = useState(false);

  /** Bearer token for the Express API, or null when signed out. */
  const getToken = useCallback(async () => {
    if (session?.access_token) return session.access_token;
    const { data } = await supabase.auth.getSession();
    return data.session?.access_token ?? null;
  }, [session]);

  /* Initial loading is handled by the database-first `load` callback below. */
  /*
    useEffect(() => {
    let cancelled = false;
    (async () => {
      setLoading(true);
      setError(null);
      try {
        const token = session?.access_token ?? (await supabase.auth.getSession()).data.session?.access_token;
        if (!token) throw new Error('Not signed in');
        const res = await apiFetch('/notifications', {
          headers: { Authorization: `Bearer ${token}` },
        });
        const json = (await res.json().catch(() => null)) as {
          notifications?: {
            id: string; type: string; title: string; body: string | null;
            reference_id: string | null; read_at: string | null; created_at: string;
          }[];
          unread?: number; message?: string;
        } | null;
        if (!res.ok) throw new Error(json?.message || `Backend responded ${res.status}`);
        if (cancelled) return;
        setItems(
          (json?.notifications ?? []).map((n) => {
            const mapped = toneForType(n.type);
            return {
              id: n.id, kind: n.type, title: n.title, detail: n.body ?? '',
              time: timeAgo(n.created_at), tone: mapped.tone, icon: mapped.icon,
              refId: n.reference_id, read: n.read_at !== null,
            };
          }),
        );
        setUnread(json?.unread ?? 0);
      } catch (e) {
        if (!cancelled) setError(describeApiFailure(e, 'Failed to load notifications'));
      } finally {
        if (!cancelled) setLoading(false);
      }
    })();
    return () => {
      cancelled = true;
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [session?.access_token]);
  */

  const load = useCallback(async () => {
    setLoading(true);
    setError(null);
    const cacheKey = session?.user?.id ? `${NOTIFICATION_CACHE_PREFIX}${session.user.id}` : null;
    let hasCachedFeed = false;
    if (cacheKey) {
      try {
        const cachedValue = await AsyncStorage.getItem(cacheKey);
        if (cachedValue) {
          const cached = JSON.parse(cachedValue) as NotificationCache;
          if (Array.isArray(cached.notifications)) {
            hasCachedFeed = true;
            setItems(mapNotifications(cached.notifications));
            setUnread(cached.unread);
            setLoading(false);
          }
        }
      } catch {
        // A corrupt or unavailable cache must not block the live request.
      }
    }
    try {
      const token = await getToken();
      if (!token) throw new Error('Not signed in');
      const res = await apiFetch('/notifications', { timeoutMs: 1_500, silent: true,
        headers: { Authorization: `Bearer ${token}` },
      });
      const json = (await res.json().catch(() => null)) as {
        notifications?: ApiNotification[];
        unread?: number; message?: string;
      } | null;
      if (!res.ok) throw new Error(json?.message || `Backend responded ${res.status}`);
      const notifications = json?.notifications ?? [];
      setItems(mapNotifications(notifications));
      setUnread(json?.unread ?? notifications.filter((notification) => notification.read_at === null).length);
      if (cacheKey) {
        try {
          await AsyncStorage.setItem(cacheKey, JSON.stringify({
            notifications,
            unread: json?.unread ?? 0,
            cachedAt: new Date().toISOString(),
          } satisfies NotificationCache));
        } catch (cacheError) {
          console.warn('[notifications] Could not update local cache:', cacheError);
        }
      }
    } catch (e) {
      if (cacheKey && !hasCachedFeed) {
        try {
          const cachedValue = await AsyncStorage.getItem(cacheKey);
          if (cachedValue) {
            const cached = JSON.parse(cachedValue) as NotificationCache;
            if (Array.isArray(cached.notifications)) {
              setItems(mapNotifications(cached.notifications));
              setUnread(cached.unread);
              setError('Showing cached notifications. We could not check for new updates.');
              return;
            }
          }
        } catch {
          // A corrupt or unavailable cache must not hide the original error.
        }
      }
      if (!hasCachedFeed) {
        setError(describeApiFailure(e, 'Failed to load notifications'));
      }
    } finally {
      setLoading(false);
    }
  }, [getToken, session?.user?.id]);

  useEffect(() => {
    void load();
  }, [load]);

  const invites = useMemo(() => items.filter((i) => i.kind === 'share_invite'), [items]);
  const others = useMemo(() => items.filter((i) => i.kind !== 'share_invite'), [items]);

  async function respond(item: Item, action: 'accept' | 'decline') {
    if (!item.refId || respondingId) return;
    setRespondingId(item.refId);
    try {
      const token = await getToken();
      if (!token) throw new Error('Not signed in');
      const res = await apiFetch(`/accounts/invites/${item.refId}/${action}`, {
        method: 'POST',
        headers: { Authorization: `Bearer ${token}` },
      });
      const json = (await res.json().catch(() => null)) as { message?: string } | null;
      if (!res.ok) throw new Error(json?.message || `Backend responded ${res.status}`);
      await load();
    } catch (e) {
      setError(describeApiFailure(e, 'Could not respond to the invite'));
    } finally {
      setRespondingId(null);
    }
  }

  async function markAllRead() {
    if (unread === 0 || markingRead) return;
    setMarkingRead(true);
    try {
      const token = await getToken();
      if (!token) throw new Error('Not signed in');
      await apiFetch('/notifications/read', {
        method: 'POST',
        headers: { Authorization: `Bearer ${token}` },
      });
      await load();
    } catch (e) {
      setError(describeApiFailure(e, 'Could not mark notifications as read'));
    } finally {
      setMarkingRead(false);
    }
  }

  return (
    <ScreenShell title="Notifications" showBack>
      {loading ? (
        <View style={styles.loaderWrap}>
          <TileLoader label="Loading notifications" size="md" />
        </View>
      ) : null}
      {error ? <Text style={styles.errorText}>{error}</Text> : null}
      <ContentCard
        style={styles.notificationsCard}
        eyebrow="Inbox"
        title={
          unread > 0
            ? `${unread} unread of ${items.length}`
            : items.length > 0
              ? `${items.length} ΓÇö all caught up`
              : 'No notifications yet'
        }
        action={unread > 0 ? (
          <Pressable
            onPress={() => void markAllRead()}
            disabled={markingRead}
            style={({ pressed }) => [styles.readAllBtn, pressed && { opacity: 0.7 }]}
            accessibilityRole="button"
            accessibilityLabel="Mark all notifications as read"
          >
            <Text style={styles.readAllText}>{markingRead ? 'Marking...' : 'Mark all read'}</Text>
          </Pressable>
        ) : undefined}
      >
        {items.length === 0 ? (
          <View style={styles.emptyWrap}>
            <Ionicons name="notifications-off-outline" size={28} color={c.muted} />
            <Text style={[styles.emptyText, { color: c.muted }]}>
              You are all caught up ΓÇö invites and updates will appear here.
            </Text>
          </View>
        ) : (
          <>
            {invites.length > 0 && (
              <Text style={[styles.sectionLabel, { color: c.muted }]}>
                Shared-user invites ({invites.length})
              </Text>
            )}
            {invites.map((item) => (
              <NotifRow
                key={item.id}
                item={item}
                styles={styles}
                busy={respondingId === item.refId}
                disabled={respondingId !== null}
                onAccept={() => void respond(item, 'accept')}
                onDecline={() => void respond(item, 'decline')}
              />
            ))}
            {others.length > 0 && invites.length > 0 && (
              <Text style={[styles.sectionLabel, { color: c.muted }]}>Other updates</Text>
            )}
            {others.map((item) => (
              <NotifRow key={item.id} item={item} styles={styles} />
            ))}
          </>
        )}
      </ContentCard>
    </ScreenShell>
  );
}

function NotifRow({
  item, styles, busy = false, disabled = false, onAccept, onDecline,
}: {
  item: Item;
  styles: ReturnType<typeof makeStyles>;
  busy?: boolean;
  disabled?: boolean;
  onAccept?: () => void;
  onDecline?: () => void;
}) {
  const palette = PALETTE[item.tone];
  const isInvite = item.kind === 'share_invite' && !!item.refId;
  return (
    <View style={styles.row}>
      <View style={[styles.icon, { backgroundColor: palette.background }]}>
        <Ionicons name={item.icon} size={20} color={palette.icon} />
      </View>
      <View style={styles.copy}>
        <View style={styles.titleLine}>
          <Text numberOfLines={2} style={styles.title}>{item.title}</Text>
          {!item.read && <View style={styles.unreadDot} />}
        </View>
        {item.detail ? (
          <Text numberOfLines={3} style={styles.detail}>{item.detail}</Text>
        ) : null}
        <Text style={styles.time}>{item.time}</Text>
        {isInvite && onAccept && onDecline ? (
          <View style={styles.inviteActions}>
            <Pressable
              disabled={disabled}
              onPress={onAccept}
              style={({ pressed }) => [
                styles.inviteBtn, styles.inviteAccept,
                pressed && { opacity: 0.75 }, disabled && { opacity: 0.6 },
              ]}
              accessibilityRole="button"
              accessibilityLabel={`Accept invite: ${item.title}`}
            >
              <Text style={styles.inviteAcceptText}>{busy ? 'Accepting...' : 'Accept'}</Text>
            </Pressable>
            <Pressable
              disabled={disabled}
              onPress={onDecline}
              style={({ pressed }) => [
                styles.inviteBtn, styles.inviteDecline,
                pressed && { opacity: 0.75 }, disabled && { opacity: 0.6 },
              ]}
              accessibilityRole="button"
              accessibilityLabel={`Decline invite: ${item.title}`}
            >
              <Text style={styles.inviteDeclineText}>{busy ? 'Working...' : 'Decline'}</Text>
            </Pressable>
          </View>
        ) : null}
      </View>
    </View>
  );
}

function makeStyles(c: ThemeColors) {
  return StyleSheet.create({
    loaderWrap: { flex: 1, alignItems: 'center', justifyContent: 'center', paddingVertical: 60 },
    notificationsCard: { padding: 12, borderRadius: 14, marginBottom: 10 },
    hint: { color: c.muted, fontSize: 12, fontFamily: fonts.medium },
    errorText: { color: '#C33D3D', fontSize: 12, fontFamily: fonts.bold, marginBottom: 8 },
    readAllBtn: {
      alignSelf: 'flex-end', borderRadius: 999, backgroundColor: c.accentSoft,
      paddingHorizontal: 11, paddingVertical: 6, marginBottom: 2,
    },
    readAllText: { color: c.accent, fontSize: 10, fontFamily: fonts.bold },
    emptyWrap: { alignItems: 'center', justifyContent: 'center', paddingVertical: 20, gap: 6 },
    emptyText: { fontSize: 11, textAlign: 'center', fontFamily: fonts.medium, lineHeight: 16 },
    sectionLabel: {
      fontSize: 9, letterSpacing: 1, textTransform: 'uppercase',
      fontFamily: fonts.extrabold, marginTop: 7, marginBottom: 2,
    },
    row: { flexDirection: 'row', gap: 9, paddingVertical: 8 },
    icon: { width: 36, height: 36, borderRadius: 11, alignItems: 'center', justifyContent: 'center' },
    copy: { flex: 1 },
    titleLine: { flexDirection: 'row', alignItems: 'center', gap: 6 },
    title: { flex: 1, color: c.text, fontSize: 12, lineHeight: 16, fontFamily: fonts.extrabold },
    unreadDot: { width: 7, height: 7, borderRadius: 4, backgroundColor: c.orange },
    detail: { color: c.muted, fontSize: 11, lineHeight: 15, marginTop: 2, fontFamily: fonts.medium },
    time: { color: c.muted, fontSize: 9, marginTop: 3, fontFamily: fonts.medium, opacity: 0.85 },
    inviteActions: { flexDirection: 'row', gap: 6, marginTop: 7 },
    inviteBtn: {
      flex: 1, borderRadius: 8, paddingVertical: 7,
      alignItems: 'center', justifyContent: 'center',
    },
    inviteAccept: { backgroundColor: '#16A34A' },
    inviteAcceptText: { color: '#FFFFFF', fontSize: 10, fontFamily: fonts.extrabold },
    inviteDecline: { backgroundColor: 'transparent', borderWidth: 1, borderColor: c.line },
    inviteDeclineText: { color: c.muted, fontSize: 10, fontFamily: fonts.bold },
  });
}

import { useState } from 'react';
import { Pressable, StyleSheet, Switch, View } from 'react-native';
import { AppText as Text } from '../../components/app-text';
import { Ionicons } from '@expo/vector-icons';
import { ScreenShell } from '../../components/screen-shell';
import { ContentCard } from '../../components/content-card';
import { FONT_SIZE_OPTIONS, fonts, useTheme, type FontSizeOption } from '../../theme';

type Pref = { key: string; icon: keyof typeof Ionicons.glyphMap; label: string; sub: string; value: boolean };

const INITIAL: Pref[] = [
  { key: 'notifications', icon: 'notifications-outline', label: 'Notifications', sub: 'Harvest & sync updates', value: true },
  { key: 'autoSync', icon: 'sync-outline', label: 'Auto-sync', sub: 'Refresh sensor data automatically', value: true },
  { key: 'powerAlerts', icon: 'warning-outline', label: 'Power alerts', sub: 'Notify on low battery', value: false },
  { key: 'haptics', icon: 'finger-print-outline', label: 'Haptic feedback', sub: 'Vibrate on tile press', value: true },
];

export default function PreferencesScreen() {
  const { colors: c, fonts: f, mode, toggleMode, fontSize, setFontSize, fs } = useTheme();
  const [prefs, setPrefs] = useState(INITIAL);

  const toggle = (key: string) =>
    setPrefs((prev) => prev.map((p) => (p.key === key ? { ...p, value: !p.value } : p)));

  return (
    <ScreenShell title="Preferences" showBack>
      {/* Theme */}
      <ContentCard eyebrow="Theme" title="Appearance">
        <View style={[styles.themeRow, { backgroundColor: c.surfaceMuted, borderColor: c.line }]}>
          <View style={[styles.themeIcon, { backgroundColor: c.accentSoft }]}>
            <Ionicons name={mode === 'dark' ? 'moon' : 'sunny'} size={18} color={c.onAccentSoft} />
          </View>
          <View style={styles.text}>
            <Text style={[styles.label, { color: c.text, fontFamily: f.semibold }]}>
              {mode === 'dark' ? 'Dark mode' : 'Light mode'}
            </Text>
            <Text style={[styles.sub, { color: c.muted, fontFamily: f.regular }]}>
              {mode === 'dark' ? 'Easy on the eyes at night' : 'Bright and clear during the day'}
            </Text>
          </View>
          <Switch
            value={mode === 'dark'}
            onValueChange={toggleMode}
            accessibilityLabel="Toggle dark mode"
            trackColor={{ false: c.line, true: c.accent }}
            thumbColor={mode === 'dark' ? c.onAccent : '#FFFFFF'}
            ios_backgroundColor={c.line}
          />
        </View>
      </ContentCard>

      {/* Font size ΓÇö body-text base (16 / 20 / 24), persisted device-wide */}
      <ContentCard eyebrow="Font size" title="Text size">
        <View style={styles.sizeRow}>
          {FONT_SIZE_OPTIONS.map((o) => {
            const active = fontSize === o.value;
            return (
              <Pressable
                key={o.value}
                onPress={() => setFontSize(o.value as FontSizeOption)}
                accessibilityRole="radio"
                accessibilityState={{ selected: active }}
                accessibilityLabel={`${o.label}, ${o.hint}`}
                style={[
                  styles.sizeCard,
                  {
                    backgroundColor: active ? c.accent : c.surfaceMuted,
                    borderColor: active ? c.accent : c.line,
                  },
                ]}
              >
                <Text
                  style={[
                    styles.sizePreview,
                    {
                      color: active ? c.onAccent : c.text,
                      fontFamily: f.bold,
                      fontSize: o.value >= 18 ? o.value : fs(o.value),
                    },
                  ]}
                >
                  Ag
                </Text>
                <Text
                  style={[
                    styles.modeLabel,
                    { color: active ? c.onAccent : c.text, fontFamily: active ? f.bold : f.semibold },
                  ]}
                >
                  {o.label}
                </Text>
                <Text
                  style={[
                    styles.modeSub,
                    { color: active ? c.onAccent : c.muted, opacity: active ? 0.85 : 1, fontFamily: f.regular },
                  ]}
                >
                  {o.value}px
                </Text>
              </Pressable>
            );
          })}
        </View>
        <View style={[styles.previewBox, { backgroundColor: c.surfaceMuted, borderColor: c.line }]}>
          <Text style={{ color: c.text, fontFamily: f.regular, fontSize: fs(14), lineHeight: fs(14) * 1.5 }}>
            Body text renders at {fontSize}px. Headings stay fixed so hierarchy is preserved.
          </Text>
        </View>
      </ContentCard>

      {/* General preferences */}
      <ContentCard eyebrow="Settings">
        {prefs.map((p, i) => (
          <View key={p.key} style={[styles.row, { borderBottomColor: c.line }, i === prefs.length - 1 ? styles.rowLast : null]}>
            <View style={[styles.icon, { backgroundColor: c.accentSoft }]}>
              <Ionicons name={p.icon} size={17} color={c.onAccentSoft} />
            </View>
            <View style={styles.text}>
              <Text style={[styles.label, { color: c.text, fontFamily: f.semibold }]}>{p.label}</Text>
              <Text style={[styles.sub, { color: c.muted, fontFamily: f.regular }]}>{p.sub}</Text>
            </View>
            <Switch
              value={p.value}
              onValueChange={() => toggle(p.key)}
              trackColor={{ false: c.line, true: c.butter }}
              thumbColor={p.value ? c.accent : '#FFFFFF'}
            />
          </View>
        ))}
      </ContentCard>
      <Text style={[styles.hint, { color: c.muted, fontFamily: f.regular }]}>
        Theme and text size are saved on this device and applied across the whole app.
      </Text>
    </ScreenShell>
  );
}

const styles = StyleSheet.create({
  modeLabel: { fontSize: 14 },
  modeSub: { fontSize: 10, lineHeight: 14 },
  themeRow: {
    flexDirection: 'row',
    alignItems: 'center',
    borderRadius: 16,
    borderWidth: 1,
    padding: 10,
  },
  themeIcon: {
    width: 38,
    height: 38,
    borderRadius: 13,
    alignItems: 'center',
    justifyContent: 'center',
    marginRight: 11,
  },
  sizeRow: { flexDirection: 'row', gap: 10 },
  sizeCard: {
    flex: 1,
    borderRadius: 14,
    borderWidth: 2,
    padding: 12,
    alignItems: 'center',
    gap: 2,
  },
  sizePreview: { lineHeight: 30 },
  previewBox: {
    marginTop: 10,
    borderRadius: 12,
    borderWidth: 1,
    padding: 12,
  },
  row: {
    flexDirection: 'row',
    alignItems: 'center',
    paddingVertical: 10,
    borderBottomWidth: 1,
  },
  rowLast: { borderBottomWidth: 0 },
  icon: {
    width: 32,
    height: 32,
    borderRadius: 10,
    alignItems: 'center',
    justifyContent: 'center',
    marginRight: 12,
  },
  text: { flex: 1 },
  label: { fontSize: 14 },
  sub: { fontSize: 11, marginTop: 1 },
  hint: { fontSize: 11, textAlign: 'center', marginTop: 4 },
});

import { useEffect, useRef, useState } from 'react';
import { ActivityIndicator, Alert, Image, Pressable, StyleSheet, Switch, View, Modal } from 'react-native';
import { AppText as Text } from '../../components/app-text';
import { Ionicons } from '@expo/vector-icons';
import * as ImagePicker from 'expo-image-picker';
import { useRouter, usePathname, type Href } from 'expo-router';
import { ScreenShell } from '../../components/screen-shell';
import { TileLoader } from '../../components/tile-loader';
import { supabase, signOut } from '../../lib/supabase';
import { apiFetch } from '../../lib/api';
import { useTheme, fonts, type ThemeColors } from '../../theme';
import { useAppTour } from '../../hooks/use-app-tour';

const MUTED = 'rgba(10, 42, 74, 0.62)';
const LINE = 'rgba(10, 42, 74, 0.1)';

type IconName = keyof typeof Ionicons.glyphMap;

type HubButton = {
  icon: IconName;
  label: string;
  sub: string;
  href: Href;
};

type HubSection = { title: string; items: HubButton[] };

type AccessSummary = {
  invited: number;
  pending: number;
};

const SECTIONS: HubSection[] = [
  {
    title: 'AUDIT TRAIL',
    items: [{ icon: 'flash-outline', label: 'History/Activity Log', sub: 'Action timestamps', href: '/pages/activity' as Href }],
  },
  {
    title: 'DEVICE MANAGEMENT',
    items: [
      { icon: 'wifi-outline', label: 'Connections', sub: 'Manage paired devices', href: '/pages/device' },
      { icon: 'people-outline', label: 'Manage Access', sub: 'Loading accessΓÇª', href: '/pages/accounts' },
      { icon: 'options-outline', label: 'System Thresholds', sub: 'Tile floor, degradation & watch list rules', href: '/pages/thresholds' },
    ],
  },
  {
    title: 'UTILITY & RATES',
    items: [
      { icon: 'wifi-outline', label: 'Meralco', sub: 'Current Provider', href: '/pages/preferences' },
      { icon: 'flash-outline', label: 'Electricity Rate', sub: 'Auto-synced from database', href: '/pages/energy' },
    ],
  },
  {
    title: 'APP SETTINGS',
    items: [
      { icon: 'person-circle-outline', label: 'Profile', sub: 'Edit account', href: '/pages/edit-profile' },
      { icon: 'options-outline', label: 'Preferences', sub: 'Theme, units & notifications', href: '/pages/preferences' },
      { icon: 'information-circle-outline', label: 'About app', sub: 'Version, components & credits', href: '/pages/about' },
      { icon: 'help-circle-outline', label: 'FAQ', sub: 'Frequently asked questions', href: '/pages/faq' as Href },
    ],
  },
];

export default function ProfileScreen() {
  const { colors: c, fonts: f } = useTheme();
  const styles = makeStyles(c, f);
  const PRUSSIAN = c.accent;
  const BUTTER = c.butter;
  const MUTED = c.muted;
  const LINE = c.line;
  const DANGER = c.danger;
  const WHITE = c.onAccent;
  const OK = c.ok;
  const BAD = c.danger;
  const router = useRouter();
  const [userId, setUserId] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);
  const [email, setEmail] = useState<string | null>(null);
  const [fullName, setFullName] = useState<string | null>(null);
  const [role, setRole] = useState<string | null>(null);
  const [avatarUrl, setAvatarUrl] = useState<string | null>(null);
  const [uploadingAvatar, setUploadingAvatar] = useState(false);
  // Photo picked in the image picker, waiting for the user to confirm in the
  // save modal before it is uploaded.
  const [pendingImage, setPendingImage] = useState<{ uri: string; mimeType?: string } | null>(null);
  const [showLogoutModal, setShowLogoutModal] = useState(false);
  const [twoFactorEnabled, setTwoFactorEnabled] = useState(false);
  const [updatingTwoFactor, setUpdatingTwoFactor] = useState(false);
  const [accessSummary, setAccessSummary] = useState<AccessSummary | null>(null);
  const { restartTour } = useAppTour();
  const pathname = usePathname();
  // Guards the replay action while we hop back to the dashboard, so a double
  // tap cannot start the tour twice.
  const replaying = useRef(false);

  /**
   * Replay the quick tour. The tour highlights home-screen elements, so we
   * navigate back to the dashboard first and start the walkthrough once the
   * home screen has had a chance to mount its targets.
   */
  const handleReplayTour = () => {
    if (replaying.current) return;
    replaying.current = true;
    if (pathname === '/home') {
      restartTour();
      replaying.current = false;
      return;
    }
    router.replace('/home' as Href);
    // Give the router time to mount the dashboard, then start the tour.
    setTimeout(() => {
      restartTour();
      replaying.current = false;
    }, 650);
  };

  useEffect(() => {
    (async () => {
      try {
        const { data: userData, error: userErr } = await supabase.auth.getUser();
        if (userErr) throw userErr;
        setEmail(userData.user?.email ?? null);
        setAvatarUrl(userData.user?.user_metadata?.avatar_url ?? null);
        setTwoFactorEnabled(userData.user?.user_metadata?.two_factor_enabled === true);
        setUserId(userData.user?.id ?? null);
        if (userData.user) {
          const { data: sessionData } = await supabase.auth.getSession();
          const token = sessionData.session?.access_token;
          if (token) {
            void (async () => {
              try {
              const headers = { Authorization: `Bearer ${token}` };
              const [sharedResponse, invitesResponse] = await Promise.all([
                apiFetch('/accounts?shared=1', { headers, timeoutMs: 1_000, silent: true }),
                apiFetch('/accounts/invites', { headers, timeoutMs: 1_000, silent: true }),
              ]);
              if (sharedResponse.ok && invitesResponse.ok) {
                const sharedJson = (await sharedResponse.json()) as { accounts?: unknown[] };
                const invitesJson = (await invitesResponse.json()) as {
                  received?: { status?: string }[];
                  sent?: { status?: string }[];
                };
                const pendingReceived = (invitesJson.received ?? []).filter((invite) => invite.status === 'pending').length;
                const pendingSent = (invitesJson.sent ?? []).filter((invite) => invite.status === 'pending').length;
                setAccessSummary({
                  invited: sharedJson.accounts?.length ?? 0,
                  pending: pendingReceived + pendingSent,
                });
              }
              } catch {
                // Access counts are supplementary and must not delay the profile.
              }
            })();
          }
          const { data: rows, error: profErr } = await supabase
            .from('user_accounts')
            .select('firstname, lastname, role')
            .eq('id', userData.user.id)
            .maybeSingle();
          if (!profErr && rows) {
            setFullName(
              [rows.firstname, rows.lastname].filter(Boolean).join(' ') || null,
            );
            setRole(rows.role ?? null);
          }
        }
      } catch {
        // Non-fatal ΓÇö hero falls back to placeholders.
      } finally {
        setLoading(false);
      }
    })();
  }, []);

  const sections = SECTIONS.map((section) => ({
    ...section,
    items: section.items.map((item) =>
      item.label === 'Manage Access'
        ? {
            ...item,
            sub: accessSummary
              ? `${accessSummary.invited} invited ┬╖ ${accessSummary.pending} pending`
              : item.sub,
          }
        : item,
    ),
  }));

  const handleTwoFactorToggle = async (enabled: boolean) => {
    const previous = twoFactorEnabled;
    setTwoFactorEnabled(enabled);
    setUpdatingTwoFactor(true);
    try {
      const { error } = await supabase.auth.updateUser({
        data: { two_factor_enabled: enabled },
      });
      if (error) throw error;
      Alert.alert(
        enabled ? 'Two-factor authentication enabled' : 'Two-factor authentication disabled',
        enabled
          ? `A one-time code will be sent to ${email ?? 'your email'} every time you sign in.`
          : 'Your password will be enough to sign in.',
      );
    } catch (error) {
      setTwoFactorEnabled(previous);
      Alert.alert('Could not update two-factor authentication', error instanceof Error ? error.message : 'Please try again.');
    } finally {
      setUpdatingTwoFactor(false);
    }
  };

  /** Opens the device photo library; the chosen photo is previewed in the save modal. */
  const handleAvatarPress = async () => {
    try {
      const perm = await ImagePicker.requestMediaLibraryPermissionsAsync();
      if (!perm.granted) {
        Alert.alert('Permission needed', 'Allow photo library access to set a profile picture.');
        return;
      }
      const result = await ImagePicker.launchImageLibraryAsync({
        mediaTypes: ImagePicker.MediaTypeOptions.Images,
        allowsEditing: true,
        aspect: [1, 1],
        quality: 0.8,
      });
      if (result.canceled || !result.assets?.length) return;
      const asset = result.assets[0];
      setPendingImage({ uri: asset.uri, mimeType: asset.mimeType });
    } catch {
      Alert.alert('Error', 'Could not open the photo library. Please try again.');
    }
  };

  /** Uploads the confirmed photo to the "avatars" bucket and links it to the account. */
  const handleAvatarSave = async () => {
    if (!pendingImage || !userId) return;
    setUploadingAvatar(true);
    try {
      const ext = pendingImage.uri.split('.').pop()?.split('?')[0] ?? 'jpg';
      const path = `${userId}/avatar.${ext}`;
      const res = await fetch(pendingImage.uri);
      const blob = await res.blob();
      const { error: upErr } = await supabase.storage
        .from('avatars')
        .upload(path, blob, { contentType: pendingImage.mimeType ?? 'image/jpeg', upsert: true });
      if (upErr) throw upErr;
      const { data: pub } = supabase.storage.from('avatars').getPublicUrl(path);
      const url = `${pub.publicUrl}?t=${Date.now()}`; // bust cache
      const { error: metaErr } = await supabase.auth.updateUser({ data: { avatar_url: url } });
      if (metaErr) throw metaErr;
      setAvatarUrl(url);
      setPendingImage(null);
      Alert.alert('Done', 'Profile picture updated.');
    } catch (e) {
      Alert.alert(
        'Upload failed',
        e instanceof Error
          ? `${e.message} (Make sure a public "avatars" storage bucket exists in Supabase.)`
          : 'Upload failed',
      );
    } finally {
      setUploadingAvatar(false);
    }
  };

  const handleAvatarCancel = () => {
    if (!uploadingAvatar) setPendingImage(null);
  };

  const handleLogoutConfirm = async () => {
    try {
      // Session-based: clear the Supabase session completely (the AuthGate
      // then locks every protected link until the next successful login).
      await signOut();
      
      // Clear any cached user data
      setShowLogoutModal(false);
      
      // Redirect to login screen
      router.replace('/login');
    } catch (error) {
      Alert.alert('Error', 'Could not sign out. Please try again.');
      setShowLogoutModal(false);
    }
  };

  const handleLogoutCancel = () => {
    setShowLogoutModal(false);
  };

  if (loading) {
    return (
      <ScreenShell title="Profile" scroll={false}>
        <View style={styles.loaderScreen}>
          <TileLoader label="Loading profile" size="md" />
        </View>
      </ScreenShell>
    );
  }

  const displayName = fullName ?? email ?? 'Signed-in user';

  return (
    <ScreenShell title="Profile">
      <View style={styles.profileHeader}>
        <Pressable
          onPress={handleAvatarPress}
          disabled={uploadingAvatar}
          style={({ pressed }) => [pressed && !uploadingAvatar && { opacity: 0.7 }]}
          accessibilityRole="button"
          accessibilityLabel="Change profile picture"
        >
          {avatarUrl ? (
            <Image source={{ uri: avatarUrl }} style={styles.profileAvatar} />
          ) : (
            <View style={styles.profileAvatarPlaceholder}>
              <Text style={styles.profileAvatarText}>{displayName.charAt(0).toUpperCase()}</Text>
            </View>
          )}
          <View style={styles.profileCameraBadge}>
            <Ionicons name={uploadingAvatar ? 'hourglass-outline' : 'camera-outline'} size={12} color={c.text} />
          </View>
        </Pressable>
        <Text style={styles.profileHeaderName}>{displayName}</Text>
        <Text style={styles.profileHeaderEmail}>{email ?? 'ΓÇö'}</Text>
      </View>

      {sections.map((section) => (
        <View key={section.title} style={styles.section}>
          <Text style={styles.sectionTitle}>{section.title}</Text>
          {section.items.map((b) => (
            <Pressable
              key={b.label}
              onPress={() => router.push(b.href)}
              style={({ pressed }) => [styles.hubBtn, pressed && { opacity: 0.7 }]}
              accessibilityRole="button"
              accessibilityLabel={b.label}
            >
              <View style={styles.hubIcon}>
                <Ionicons name={b.icon} size={18} color={c.text} />
              </View>
              <View style={styles.hubText}>
                <Text style={styles.hubLabel}>{b.label}</Text>
                <Text style={styles.hubSub}>{b.sub}</Text>
              </View>
              {b.label === 'Connection' ? (
                <View style={styles.onlineState}><View style={styles.onlineDot} /><Text style={styles.onlineText}>Online</Text></View>
              ) : b.label === 'Electricity Rate' ? (
                <View style={styles.rateState}><Text style={styles.rateValue}>Γé▒9.25 / kWh</Text><Text style={styles.rateActive}>ACTIVE</Text></View>
              ) : <Ionicons name="chevron-forward" size={17} color={MUTED} />}
            </Pressable>
          ))}
        </View>
      ))}

      {/* Quick tour replay ΓÇö the same five-step walkthrough shown on first run. */}
      <View style={styles.section}>
        <Text style={styles.sectionTitle}>HELP</Text>
        <Pressable
          onPress={handleReplayTour}
          style={({ pressed }) => [styles.hubBtn, pressed && { opacity: 0.7 }]}
          accessibilityRole="button"
          accessibilityLabel="Replay the quick tour"
          accessibilityHint="Shows a five step walkthrough of the dashboard"
        >
          <View style={styles.hubIcon}>
            <Ionicons name="sparkles-outline" size={18} color={c.text} />
          </View>
          <View style={styles.hubText}>
            <Text style={styles.hubLabel}>Replay quick tour</Text>
            <Text style={styles.hubSub}>Take the 5-step dashboard walkthrough again</Text>
          </View>
          <Ionicons name="chevron-forward" size={17} color={MUTED} />
        </Pressable>
      </View>

      <Text style={styles.sectionTitle}>SECURITY</Text>
      <View style={styles.securityCard}>
        <View style={styles.hubIcon}>
          <Ionicons name="shield-checkmark-outline" size={18} color={c.orange} />
        </View>
        <View style={styles.securityText}>
          <Text style={styles.hubLabel}>Two-factor authentication</Text>
          <Text style={styles.hubSub}>Email a one-time code after password sign-in</Text>
        </View>
        <Switch
          value={twoFactorEnabled}
          onValueChange={handleTwoFactorToggle}
          disabled={updatingTwoFactor}
          trackColor={{ false: c.line, true: c.orange }}
          thumbColor="#FFFFFF"
          accessibilityLabel="Enable two-factor authentication"
        />
      </View>

      {/* Logout button */}
      <Pressable 
        style={({ pressed }) => [styles.logoutBtn, pressed && { opacity: 0.7 }]}
        onPress={() => setShowLogoutModal(true)}
        accessibilityRole="button"
        accessibilityLabel="Log out"
      >
        <Ionicons name="log-out-outline" size={18} color="#FFFFFF" style={{ marginRight: 8 }} />
        <Text style={styles.logoutText}>Log out</Text>
      </Pressable>

      {/* Logout Confirmation Modal */}
      <Modal
        visible={showLogoutModal}
        transparent
        animationType="fade"
        onRequestClose={handleLogoutCancel}
      >
        <View style={[styles.modalOverlay, { backgroundColor: 'rgba(0, 0, 0, 0.5)' }]}>
          <View style={[styles.modalContent, { backgroundColor: c.surface, borderRadius: 16, padding: 20, shadowColor: '#000', shadowOffset: { width: 0, height: 4 }, shadowOpacity: 0.3, shadowRadius: 8, elevation: 5 }]}>
            <Text style={[styles.modalTitle, { color: c.text, fontSize: 18, fontWeight: '800', marginBottom: 8, textAlign: 'center' }]}>Log out</Text>
            <Text style={[styles.modalText, { color: MUTED, fontSize: 14, lineHeight: 20, marginBottom: 20, textAlign: 'center' }]}>
              Are you sure you want to sign out of your account?
            </Text>
            <View style={[styles.modalButtons, { flexDirection: 'row', gap: 12 }]}>
              <Pressable 
                onPress={handleLogoutCancel}
                style={({ pressed }) => [styles.cancelButton, { backgroundColor: c.surface, borderColor: LINE, borderWidth: 1, paddingVertical: 12, borderRadius: 8, alignItems: 'center' }, pressed && { opacity: 0.7 }]}
              >
                <Text style={[styles.cancelText, { color: c.text, fontSize: 14, fontWeight: '600' }]}>Cancel</Text>
              </Pressable>
              <Pressable 
                onPress={handleLogoutConfirm}
                style={({ pressed }) => [styles.confirmButton, { backgroundColor: DANGER, paddingVertical: 12, borderRadius: 8, alignItems: 'center' }, pressed && { opacity: 0.7 }]}
              >
                <Text style={[styles.confirmText, { color: '#FFFFFF', fontSize: 14, fontWeight: '600' }]}>Log out</Text>
              </Pressable>
            </View>
          </View>
        </View>
      </Modal>

      {/* Save-photo modal */}
      <Modal
        visible={pendingImage !== null}
        transparent
        animationType="fade"
        onRequestClose={handleAvatarCancel}
      >
        <View style={styles.modalOverlay}>
          <View style={styles.modalContent}>
            <Text style={[styles.modalTitle, { color: c.text }]}>Save profile picture?</Text>
            <View style={styles.modalPreviewWrap}>
              {pendingImage ? (
                <Image source={{ uri: pendingImage.uri }} style={styles.modalPreview} />
              ) : null}
              {uploadingAvatar ? (
                <View style={styles.modalPreviewBusy}>
                  <ActivityIndicator color={PRUSSIAN} size="large" />
                </View>
              ) : null}
            </View>
            <Text style={[styles.modalText, { color: MUTED }]}>
              {uploadingAvatar ? 'Uploading your photoΓÇª' : 'This will replace your current profile picture.'}
            </Text>
            <View style={styles.modalButtons}>
              <Pressable
                onPress={handleAvatarCancel}
                disabled={uploadingAvatar}
                style={({ pressed }) => [
                  styles.cancelButton,
                  pressed && !uploadingAvatar && { opacity: 0.7 },
                ]}
                accessibilityRole="button"
                accessibilityLabel="Cancel profile picture change"
              >
                <Text style={styles.cancelText}>Cancel</Text>
              </Pressable>
              <Pressable
                onPress={handleAvatarSave}
                disabled={uploadingAvatar}
                style={({ pressed }) => [
                  styles.saveButton,
                  pressed && !uploadingAvatar && { opacity: 0.85 },
                ]}
                accessibilityRole="button"
                accessibilityLabel="Save profile picture"
              >
                {uploadingAvatar ? (
                  <ActivityIndicator color={WHITE} size="small" />
                ) : (
                  <Text style={styles.saveText}>Save</Text>
                )}
              </Pressable>
            </View>
          </View>
        </View>
      </Modal>
    </ScreenShell>
  );
}

const makeStyles = (c: ThemeColors, f: any) => {
  const PRUSSIAN = c.accent;
  const MUTED = c.muted;
  const LINE = c.line;
  const BUTTER = c.butter;
