    borderColor: BUTTER,
  },
  avatarText: { color: c.text, fontSize: 32, fontWeight: '900', fontFamily: f.extrabold },
  camBadge: {
    position: 'absolute',
    right: 0,
    bottom: 0,
    width: 28,
    height: 28,
    borderRadius: 14,
    backgroundColor: c.surface,
    borderWidth: 1,
