    alignItems: 'center',
    justifyContent: 'center',
  },
  tapHint: { color: MUTED, fontSize: 11, marginTop: 8 },
  heroName: { color: c.text, fontSize: 19, fontWeight: '900', fontFamily: f.extrabold },
  heroEmail: { color: MUTED, fontSize: 12, marginTop: 2 },
  roleChip: {
    backgroundColor: 'rgba(246, 196, 69, 0.28)',
    borderRadius: 999,
    paddingHorizontal: 12,
    paddingVertical: 4,
    marginTop: 6,
  },
  roleChipText: { color: c.text, fontSize: 11, fontWeight: '800', fontFamily: f.extrabold, textTransform: 'capitalize' },
  hubBtn: {
    flexDirection: 'row',
    alignItems: 'center',
    backgroundColor: c.surface,
    borderRadius: 16,
    borderWidth: 1,
    borderColor: LINE,
    paddingHorizontal: 14,
    paddingVertical: 11,
    marginBottom: 8,
    minHeight: 62,
  },
  hubIcon: {
    width: 30,
    height: 30,
    borderRadius: 10,
    backgroundColor: 'rgba(249, 115, 22, 0.12)',
    alignItems: 'center',
    justifyContent: 'center',
    marginRight: 10,
  },
  hubText: { flex: 1 },
  hubLabel: { color: c.text, fontSize: 12, fontWeight: '800', fontFamily: f.extrabold },
  hubSub: { color: MUTED, fontSize: 10, marginTop: 2 },
  securityCard: { flexDirection: 'row', alignItems: 'center', backgroundColor: c.surface, borderRadius: 16, borderWidth: 1, borderColor: LINE, paddingHorizontal: 14, paddingVertical: 11, marginBottom: 8, minHeight: 68 },
  securityText: { flex: 1, marginRight: 8 },
  onlineState: { flexDirection: 'row', alignItems: 'center', gap: 4 },
  onlineDot: { width: 7, height: 7, borderRadius: 4, backgroundColor: '#1764B0' },
  onlineText: { color: c.text, fontSize: 10, fontFamily: f.bold },
  rateState: { alignItems: 'flex-end' },
  rateValue: { color: c.text, fontSize: 12, fontFamily: f.extrabold },
  rateActive: { color: '#1764B0', fontSize: 8, letterSpacing: 0.8, fontFamily: f.extrabold, marginTop: 2 },
  logoutBtn: {
    backgroundColor: DANGER,
    borderRadius: 14,
    paddingVertical: 14,
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'center',
    marginTop: 14,
    marginBottom: 12,
  },
  logoutText: { color: WHITE, fontSize: 14, fontWeight: '800', fontFamily: f.extrabold },
  modalOverlay: {
    flex: 1,
    backgroundColor: 'rgba(0, 0, 0, 0.5)',
    justifyContent: 'center',
    alignItems: 'center',
  },
  modalContent: {
    width: '85%',
    backgroundColor: c.surface,
    borderRadius: 16,
    padding: 20,
    shadowColor: '#000',
    shadowOffset: { width: 0, height: 4 },
    shadowOpacity: 0.3,
    shadowRadius: 8,
    elevation: 5,
  },
  modalTitle: {
    fontSize: 18,
    fontWeight: '800',
    marginBottom: 8,
    textAlign: 'center',
  },
  modalText: {
    fontSize: 14,
    lineHeight: 20,
    marginBottom: 20,
    textAlign: 'center',
  },
  modalButtons: {
    flexDirection: 'row',
    gap: 12,
    justifyContent: 'flex-end',
  },
  cancelButton: {
    flex: 1,
    paddingVertical: 12,
    paddingHorizontal: 20,
    borderRadius: 8,
    borderWidth: 1,
    borderColor: '#0A2A4A',
