import React, { useEffect, useRef, useState } from 'react';
import { Animated, StyleSheet, View } from 'react-native';
import { AppText as Text } from './app-text';
import { Ionicons } from '@expo/vector-icons';
import {
  NETWORK_ISSUE_INFO,
  subscribeToConnectivity,
  type NetworkIssue,
} from '../lib/network';

/**
 * Global connectivity banner, mounted once at the app root.
 *
 * - Offline  ΓåÆ persistent amber "No internet connection" bar.
 * - Restored ΓåÆ green "Back online" confirmation that fades after 3s.
 * - Optional issue prop shows a one-shot banner for unstable / rate-limit /
 *   timeout problems reported by a screen.
 */
export function NetworkBanner({ issue, onDismiss }: {
  /** One-shot issue pushed by a screen (e.g. rate limited, timeout). */
  issue?: NetworkIssue | null;
  /** Called when the one-shot banner is dismissed or auto-hides. */
  onDismiss?: () => void;
}) {
  const [offline, setOffline] = useState(false);
  const [backOnline, setBackOnline] = useState(false);
  const [flash, setFlash] = useState<NetworkIssue | null>(null);
  const slide = useRef(new Animated.Value(0)).current;
  const wasOffline = useRef(false);
  const hideTimer = useRef<ReturnType<typeof setTimeout> | null>(null);

  // Track device connectivity globally.
  useEffect(() => {
    return subscribeToConnectivity((online) => {
      setOffline(!online);
      if (!online) {
        wasOffline.current = true;
        setBackOnline(false);
      } else if (wasOffline.current) {
        // Only celebrate a *restored* connection, never the initial state.
        wasOffline.current = false;
        setBackOnline(true);
        setFlash(null);
      }
    });
  }, []);

  // Show one-shot issues pushed from screens.
  useEffect(() => {
    if (!issue) return;
    setFlash(issue);
    if (hideTimer.current) clearTimeout(hideTimer.current);
    hideTimer.current = setTimeout(() => {
      setFlash(null);
      onDismiss?.();
    }, 4000);
    return () => {
      if (hideTimer.current) clearTimeout(hideTimer.current);
    };
  }, [issue, onDismiss]);

  // Auto-hide the "back online" toast.
  useEffect(() => {
    if (!backOnline) return;
    const t = setTimeout(() => setBackOnline(false), 3000);
    return () => clearTimeout(t);
  }, [backOnline]);

  const visible = offline || backOnline || flash !== null;
  const content = offline
    ? NETWORK_ISSUE_INFO.offline
    : flash
      ? NETWORK_ISSUE_INFO[flash]
      : NETWORK_ISSUE_INFO.unstable; // placeholder, only used when back online below

  useEffect(() => {
    Animated.timing(slide, {
      toValue: visible ? 1 : 0,
      duration: 220,
      useNativeDriver: true,
    }).start();
  }, [visible, slide]);

  if (!visible) return null;

  const isBackOnline = backOnline && !offline && !flash;
  const palette = isBackOnline
    ? { bg: '#DCFCE7', border: '#86EFAC', text: '#166534' }
    : { bg: '#FEF3C7', border: '#FCD34D', text: '#92400E' };

  const icon = isBackOnline ? 'checkmark-circle' : content.icon;
  const title = isBackOnline ? 'Back online' : content.title;
  const message = isBackOnline ? 'Your connection has been restored.' : content.message;

  return (
    <Animated.View
      pointerEvents="none"
      style={[styles.wrap, { opacity: slide, transform: [{ translateY: slide.interpolate({ inputRange: [0, 1], outputRange: [-8, 0] }) }] }]}
    >
      <View style={[styles.bar, { backgroundColor: palette.bg, borderColor: palette.border }]}>
        <Ionicons name={icon} size={18} color={palette.text} style={styles.icon} />
        <View style={styles.textCol}>
          <Text style={[styles.title, { color: palette.text }]}>{title}</Text>
          <Text style={[styles.message, { color: palette.text }]}>{message}</Text>
        </View>
      </View>
    </Animated.View>
  );
}

const styles = StyleSheet.create({
  wrap: {
    position: 'absolute',
    top: 0,
    left: 0,
    right: 0,
    zIndex: 1000,
    elevation: 1000,
  },
  bar: {
    flexDirection: 'row',
    alignItems: 'center',
    borderBottomWidth: 1,
    paddingHorizontal: 14,
    paddingVertical: 10,
  },
  icon: { marginRight: 10 },
  textCol: { flex: 1 },
  title: { fontSize: 13, fontWeight: '800' },
  message: { fontSize: 12, marginTop: 1, lineHeight: 16 },
});

import { useState, useEffect } from "react";
import {
  ActivityIndicator,
  KeyboardAvoidingView,
  Linking,
  Modal,
  Platform,
  Pressable,
  ScrollView,
  StyleSheet,
  TextInput,
  View,
  useWindowDimensions,
} from "react-native";
import { AppText as Text } from "./app-text";
import { useRouter } from "expo-router";
import { Ionicons } from "@expo/vector-icons";
import {
  CameraView,
  useCameraPermissions,
  type BarcodeScanningResult,
} from "expo-camera";
import { LinearGradient } from "expo-linear-gradient";
import { SafeAreaView } from "react-native-safe-area-context";
import AsyncStorage from "@react-native-async-storage/async-storage";

import { scale } from "./glass-ui";
import { fonts, useTheme, type Mode, type ThemeColors } from "../theme";
import type { IoniconName } from "../lib/network";

/* ---------------------------------- model --------------------------------- */

type Step = {
  number: string;
  short: string;
  title: string;
  copy: string;
  icon: IoniconName;
};

const STEPS: Step[] = [
  {
    number: "01",
    short: "Power on",
    title: "Power on the IoT hub",
    copy: "Connect the hub to power and wait for the status light to pulse blue.",
    icon: "power-outline",
  },
  {
    number: "02",
    short: "Join network",
    title: "Join the same network",
    copy: "Keep your phone and hub on the facility Wi-Fi during setup.",
    icon: "wifi-outline",
  },
  {
    number: "03",
    short: "Scan code",
    title: "Scan the device code",
    copy: "Find the QR label on the hub or enter its code manually below.",
    icon: "scan-outline",
  },
];

const ACTIVE_STEP = 0;

const fs = (v: number) => Math.max(scale(v), v * 0.9);
const COLUMN_MAX = 560;

function themePalette(mode: Mode, c: ThemeColors) {
  const dark = mode === "dark";
  return {
    liveDot: dark ? "#FFFFFF" : "#5CE08A",
    liveDotRing: dark ? "#000000" : "#12406E",
    cta: (dark ? ["#FFFFFF", "#D9D9D9"] : ["#F5C245", "#E0A315"]) as [
      string,
      string,
    ],
    ctaInk: dark ? "#000000" : "#0A2A4A",
    ctaShadow: dark ? "#FFFFFF" : "#B87C05",
    scanCorner: dark ? "#FFFFFF" : c.butter,
  };
}

export function ProvisioningScreen() {
  const router = useRouter();
  const { colors: c, mode } = useTheme();
  const { width, height } = useWindowDimensions();
  const [cameraPermission, requestCameraPermission] = useCameraPermissions();

  const [ssid, setSsid] = useState("");
  const [wifiPassword, setWifiPassword] = useState("");
  const [showWifiPassword, setShowWifiPassword] = useState(false);
  const [focusedField, setFocusedField] = useState<"ssid" | "password" | null>(
    null,
  );

  const [scannerVisible, setScannerVisible] = useState(false);
  const [scanLocked, setScanLocked] = useState(false);
  const [torchOn, setTorchOn] = useState(false);

  // TOUR GUIDE STATE
  const [tourVisible, setTourVisible] = useState(false);

  const [isConnecting, setIsConnecting] = useState(false);
  const [modalConfig, setModalConfig] = useState<{
    visible: boolean;
    title: string;
    message: string;
    type: "error" | "success" | "info";
    onConfirm?: () => void;
  }>({
    visible: false,
    title: "",
    message: "",
    type: "info",
  });

  const p = themePalette(mode, c);

  const compact = width < 375;
  const wide = width >= 700;
  const gutter = wide ? 24 : compact ? 14 : 20;
  const scanFrame = Math.round(Math.min(width - 76, height * 0.38, 272));

  // Initialize Tour Guide Safely with a new storage key
  useEffect(() => {
    let isMounted = true;
    // We use a fresh key here so it ignores the old cached value from your testing
    AsyncStorage.getItem("bawatpieza_tour_seen_modal").then((seen) => {
      if (isMounted && !seen) {
        setTourVisible(true);
      }
    });
    return () => {
      isMounted = false;
    };
  }, []);

  const dismissTour = () => {
    setTourVisible(false);
    AsyncStorage.setItem("bawatpieza_tour_seen_modal", "true");
  };

  const handleSsidChange = (text: string) => {
    setSsid(text);
  };

  const handlePasswordChange = (text: string) => {
    setWifiPassword(text);
  };

  const showModal = (
    title: string,
    message: string,
    type: "error" | "success" | "info",
    onConfirm?: () => void,
  ) => {
    setModalConfig({ visible: true, title, message, type, onConfirm });
  };

  const closeModal = () => {
    const { onConfirm } = modalConfig;
    setModalConfig((prev) => ({ ...prev, visible: false }));
    if (onConfirm) onConfirm();
  };

  const openWifiSettings = () => {
    const open =
      Platform.OS === "android"
        ? Linking.sendIntent("android.settings.WIFI_SETTINGS")
        : Linking.openSettings();
    void open.catch(() => Linking.openSettings().catch(() => undefined));
  };

  const simulatePair = () => {
    router.replace("/home");
  };

  const connectToHub = async () => {
    if (!ssid || !wifiPassword) {
      showModal(
        "Missing Details",
        "Please enter your Wi-Fi name and password.",
        "error",
      );
      return;
    }

    setIsConnecting(true);
    const controller = new AbortController();
    const timeout = setTimeout(() => controller.abort(), 8000); // 8-second timeout to prevent app hanging

    try {
      const formData = new URLSearchParams();
      formData.append("ssid", ssid);
      formData.append("pass", wifiPassword);

      const response = await fetch("http://192.168.4.1/connect-hub", {
        method: "POST",
        headers: {
          "Content-Type": "application/x-www-form-urlencoded",
        },
        body: formData.toString(),
        signal: controller.signal,
      });

      clearTimeout(timeout);

      if (response.ok) {
        const data = await response.json();
        if (data.status === "success") {
          const hubId = data.hub_id;
          await AsyncStorage.setItem("bawatpieza_hub_id", hubId);

          setIsConnecting(false);
          // Explicitly warn them to reconnect internet before continuing to avoid MQTT crash on Home Screen
          showModal(
            "Hub Configured!",
            "The hub is successfully joining your network.\n\nIMPORTANT: Reconnect your phone to your normal Wi-Fi (with internet) before tapping Continue.",
            "success",
            () => {
              router.replace({
                pathname: "/home",
                params: { hubId: hubId },
              });
            },
          );
        } else {
          setIsConnecting(false);
          showModal(
            "Error",
            "The hub rejected the connection. Try again.",
            "error",
          );
        }
      } else {
        setIsConnecting(false);
        showModal(
          "Error",
          "The hub rejected the connection. Try again.",
          "error",
        );
      }
    } catch (error) {
      clearTimeout(timeout);
      setIsConnecting(false);
      showModal(
        "Connection Failed",
        "Could not reach the hub. Ensure your phone is connected to the 'BawatPieza-Setup' network. Ignore any 'No Internet' warnings from your phone.",
        "error",
      );
    }
  };

  const closeScanner = () => {
    setScannerVisible(false);
    setTorchOn(false);
  };

  const openScanner = async () => {
    setScanLocked(false);
    setTorchOn(false);
    if (!cameraPermission?.granted) {
      const permission = await requestCameraPermission();
      if (!permission.granted) return;
    }
    setScannerVisible(true);
  };

  const handleBarcodeScanned = ({ data }: BarcodeScanningResult) => {
    if (scanLocked) return;
    const wifi = parseWifiQr(data);

    if (!wifi) {
      setScanLocked(true);
      showModal(
        "Not a Wi-Fi QR code",
        "Scan a Wi-Fi sharing QR code or enter the network details manually.",
        "error",
        () => {
          setScanLocked(false);
          closeScanner();
        },
      );
      return;
    }

    if (wifi.isRaw) {
      showModal(
        "Notice",
        "Could not read full credentials. Raw data set as Wi-Fi Name.",
        "info",
      );
    }

    setSsid(wifi.ssid);
    setWifiPassword(wifi.password);
    closeScanner();
  };

  return (
    <SafeAreaView style={[styles.safeArea, { backgroundColor: c.bg }]}>
      <KeyboardAvoidingView
        style={styles.safeArea}
        behavior={Platform.OS === "ios" ? "padding" : undefined}
      >
        <ScrollView
          contentContainerStyle={[
            styles.scrollContent,
            { paddingHorizontal: gutter, paddingBottom: scale(30) },
          ]}
          showsVerticalScrollIndicator={false}
          keyboardShouldPersistTaps="handled"
        >
          <View style={styles.column}>
            <View style={styles.topRow}>
              <Pressable
                onPress={() => router.back()}
                accessibilityRole="button"
                accessibilityLabel="Go back"
                hitSlop={8}
                style={({ pressed }) => [
                  styles.backButton,
                  { borderColor: c.line, backgroundColor: c.surface },
                  pressed && styles.pressed,
                ]}
              >
                <Ionicons name="arrow-back" size={fs(17)} color={c.text} />
              </Pressable>
              <View style={[styles.brandMark, { backgroundColor: c.accent }]}>
                <Ionicons name="flash" size={fs(19)} color={c.onAccent} />
              </View>
              <View style={styles.topLabelWrap}>
                <View
                  style={[styles.liveDot, { backgroundColor: p.liveDot }]}
                />
                <Text style={[styles.topLabel, { color: c.muted }]}>
                  DEVICE SETUP
                </Text>
              </View>
              <Pressable
                onPress={simulatePair}
                accessibilityRole="button"
                accessibilityLabel="Skip device setup"
                style={({ pressed }) => [
                  styles.skipPill,
                  { borderColor: c.line, backgroundColor: c.surface },
                  pressed && styles.pressed,
                ]}
              >
                <Text style={[styles.skipText, { color: c.text }]}>Skip</Text>
                <Ionicons name="arrow-forward" size={fs(13)} color={c.text} />
              </Pressable>
            </View>

            <View style={styles.intro}>
              <Text style={[styles.eyebrow, { color: c.orange }]}>
                WELCOME TO BAWATPIEZA
              </Text>
              <Text style={[styles.title, { color: c.text }]}>
                Connect your energy hub
              </Text>
              <Text style={[styles.subtitle, { color: c.muted }]}>
                A few quick steps to bring your smart floor online.
              </Text>
            </View>

            <View style={styles.steps}>
              {STEPS.map((step, index) => {
                const active = index === ACTIVE_STEP;
                const done = index < ACTIVE_STEP;
                return (
                  <View
                    key={step.number}
                    style={styles.stepItem}
                    accessibilityRole="text"
                    accessibilityLabel={`Step ${step.number} of ${STEPS.length}. ${step.title}. ${step.copy}`}
                  >
                    <View style={styles.stepRail}>
                      {index < STEPS.length - 1 && (
                        <View
                          style={[styles.stepLine, { backgroundColor: c.line }]}
                        />
                      )}
                      <View
                        style={[
                          styles.stepBadge,
                          active
                            ? {
                                backgroundColor: c.accent,
                                borderColor: c.accent,
                              }
                            : {
                                backgroundColor: c.surfaceMuted,
                                borderColor: c.line,
                              },
                        ]}
                      >
                        <Ionicons
                          name={done ? "checkmark" : step.icon}
                          size={fs(15)}
                          color={active ? c.onAccent : c.muted}
                        />
                      </View>
                    </View>
                    <Text
                      style={[
                        styles.stepNumber,
                        { color: active ? c.orange : c.muted },
                      ]}
                    >
                      {step.number}
                    </Text>
                    <Text
                      style={[
                        styles.stepLabel,
                        { color: active ? c.text : c.muted },
                      ]}
                      numberOfLines={2}
                    >
                      {step.short}
                    </Text>
                  </View>
                );
              })}
            </View>

            <View style={styles.formSection}>
              <View style={styles.cardHead}>
                <View style={styles.cardHeadCopy}>
                  <Text style={[styles.cardEyebrow, { color: c.orange }]}>
                    NETWORK DETAILS
                  </Text>
                  <Text style={[styles.cardTitle, { color: c.text }]}>
                    Finish your connection
                  </Text>
                </View>
                <View
                  style={[
                    styles.secureBadge,
                    { backgroundColor: c.accentSoft },
                  ]}
                >
                  <Ionicons
                    name="shield-checkmark-outline"
                    size={fs(17)}
                    color={c.onAccentSoft}
                  />
                </View>
              </View>
              <Text style={[styles.cardCopy, { color: c.muted }]}>
                Use the same Wi-Fi network your hub will use.
              </Text>

              {/* Disclaimer to soothe users worried about the OS "No Internet" prompt */}
              <View
                style={[
                  styles.disclaimerBox,
                  { backgroundColor: c.surfaceMuted, borderColor: c.line },
                ]}
              >
                <Ionicons
                  name="information-circle"
                  size={14}
                  color={c.accent}
                />
                <Text style={[styles.disclaimerText, { color: c.muted }]}>
