  heroPrefix: { fontSize: scale(22), marginRight: scale(2), fontFamily: fonts.extrabold },
  heroNumber: { fontSize: scale(56), lineHeight: scale(62), letterSpacing: -2, fontFamily: fonts.extrabold },
